Here is a Python function `eval_expression(expr)` that uses the Shunting-Yard algorithm (to parse the mathematical expression following the correct order of operations, parentheses, and negative numbers) and then evaluates the resulting Reverse Polish Notation (RPN). 

This avoids using Python's built-in `eval()`, making it a robust custom evaluator.

```python
def eval_expression(expr: str) -> float:
    def tokenize(expression):
        tokens = []
        i = 0
        n = len(expression)
        while i < n:
            char = expression[i]
            if char.isspace():
                i += 1
                continue

            # Handle numbers (including decimals and negative numbers)
            if char.isdigit() or char == '.':
                num_str = []
                while i < n and (expression[i].isdigit() or expression[i] == '.'):
                    num_str.append(expression[i])
                    i += 1
                tokens.append(float(''.join(num_str)) if '.' in num_str else int(''.join(num_str)))
                continue

            # Handle unary minus (negative numbers)
            if char == '-':
                # It's a unary minus if it's the first token, or follows an operator or open parenthesis
                is_unary = (not tokens or 
                            tokens[-1] in ('+', '-', '*', '/', '('))
                if is_unary:
                    # Look ahead to see if it's followed by a number
                    i += 1
                    while i < n and expression[i].isspace():
                        i += 1
                    if i < n and (expression[i].isdigit() or expression[i] == '.'):
                        num_str = ['-']
                        while i < n and (expression[i].isdigit() or expression[i] == '.'):
                            num_str.append(expression[i])
                            i += 1
                        tokens.append(float(''.join(num_str)) if '.' in num_str else int(''.join(num_str)))
                        continue
                    else:
                        raise ValueError("Invalid syntax around unary minus")

            if char in "+-*/()":
                tokens.append(char)
                i += 1
                continue

            raise ValueError(f"Invalid character: {char}")
        return tokens

    tokens = tokenize(expr)

    # Shunting-Yard Algorithm to convert Infix to RPN
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output_queue = []
    operator_stack = []

    for token in tokens:
        if isinstance(token, (int, float)):
            output_queue.append(token)
        elif token in precedence:
            while (operator_stack and operator_stack[-1] in precedence and
                   precedence[operator_stack[-1]] >= precedence[token]):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack and operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            if not operator_stack:
                raise ValueError("Mismatched parentheses")
            operator_stack.pop() # Remove '('

    while operator_stack:
        op = operator_stack.pop()
        if op == '(':
            raise ValueError("Mismatched parentheses")
        output_queue.append(op)

    # Evaluate RPN
    eval_stack = []
    for token in output_queue:
        if isinstance(token, (int, float)):
            eval_stack.append(token)
        else:
            if len(eval_stack) < 2:
                raise ValueError("Invalid expression")
            b = eval_stack.pop()
            a = eval_stack.pop()

            if token == '+':
                eval_stack.append(a + b)
            elif token == '-':
                eval_stack.append(a - b)
            elif token == '*':
                eval_stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                # Use standard division, result could be float
                eval_stack.append(a / b)

    if len(eval_stack) != 1:
        raise ValueError("Invalid expression")

    result = eval_stack[0]
    # If the result is a float that represents a whole number, return as int for cleaner output (optional)
    if isinstance(result, float) and result.is_integer():
        return int(result)
    return result
```

### Example Usage:

```python
print(eval_expression("3 + 4 * (2 - 1)"))       # Output: 7
print(eval_expression("-5 + (-3) * 2"))        # Output: -11
print(eval_expression("10 / (5 - 5)"))         # Raises ZeroDivisionError
print(eval_expression("3.5 * (2 + 4)"))        # Output: 21.0
```

